// AiXenix Cosmos Lab web client: worker for big galaxy drawing samples (exact model stars, see src/cosmos). It builds
// its own copy of the deterministic universe from the same catalogue, so ids and positions match the main thread.

type Vec3 = [number, number, number];

interface CoreApi {
  buildUniverse(galaxies: unknown[], stars?: unknown[]): unknown;
  sampleGalaxy(u: unknown, galaxyId: string, count: number, opts?: { seed?: number; region?: { centrePc: Vec3; radiusPc: number } }): RawSample;
}

import { toDrawSample, type RawSample } from './cosmosSample';

interface ContentApi {
  COSMOS_GALAXIES: unknown[];
  KNOWN_STARS: unknown[];
}

const coreModules = import.meta.glob<CoreApi>('../cosmos/index.ts');
const contentModules = import.meta.glob<ContentApi>('../content/cosmos.ts');

let ready: Promise<{ core: CoreApi; universe: unknown }> | null = null;

function init(): Promise<{ core: CoreApi; universe: unknown }> {
  if (!ready) {
    ready = (async () => {
      const lc = coreModules['../cosmos/index.ts'];
      if (!lc) throw new Error('model-missing');
      const core = await lc();
      const lt = contentModules['../content/cosmos.ts'];
      const content = lt ? await lt() : null;
      return { core, universe: core.buildUniverse(content?.COSMOS_GALAXIES ?? [], content?.KNOWN_STARS ?? []) };
    })();
  }
  return ready;
}

const scope = self as unknown as { postMessage(msg: unknown, transfer?: Transferable[]): void; onmessage: ((e: MessageEvent) => void) | null };

scope.onmessage = async (e: MessageEvent) => {
  const msg = e.data as { type: string; req: number; galaxyId: string; count: number };
  if (msg.type !== 'sample') return;
  try {
    const { core, universe } = await init();
    const d = toDrawSample(msg.galaxyId, core.sampleGalaxy(universe, msg.galaxyId, msg.count));
    const transfer: Transferable[] = [d.positions.buffer, d.colors.buffer, d.brightness.buffer];
    if (d.ids) transfer.push(d.ids.buffer);
    scope.postMessage({ req: msg.req, ok: true, ...d }, transfer);
  } catch (err) {
    scope.postMessage({ req: msg.req, ok: false, error: err instanceof Error ? err.message : String(err) });
  }
};
